"};\n"
"const uiChinese={\n"
"'连接同一局域网后读取配置。网络仅支持 2.4 GHz。':'连接设备所在局域网后可读取配置。仅支持 2.4 GHz Wi-Fi。',\n"
"'新的打印机':'新打印机','云端凭据从哪里获取？':'获取云端访问凭据',\n"
"'设备自行校时与渲染。只在分钟变化时播放约 720 毫秒的折页动画，空闲每秒刷新。':'设备独立校时与渲染，分钟切换时播放约 720 毫秒折页动画，其余时间每秒刷新。',\n"
"'中国大陆使用 28800。设备未联网校时时会显示等待校时。':'中国标准时间为 UTC+8（28800 秒）。网络校时完成前显示同步状态。',\n"
"'启用后会将所填经纬度发送至 Open-Meteo 获取天气，默认每 30 分钟更新。失败保留最近数据并退避重试。':'启用后向 Open-Meteo 发送所设经纬度，默认每 30 分钟更新天气。请求失败时保留最近数据并延后重试。',\n"
"'仅轮转勾选的时钟、天气与打印机卡片；打印机空闲或离线时仍保留卡片，便于检查连接。已完成任务保留至下一项任务。':'自动轮转仅包含已选择的卡片。空闲或离线打印机保留显示；已完成任务由下一项任务替换。',\n"
"'设置已保存到这台设备。':'设备设置已保存。','设备配置已读取。':'设备设置已读取。',\n"
"'等待内存':'内存不足，等待重试','凭据被拒绝':'访问凭据无效',\n"
"'这是独立测试分支，不替换多屏灵犀应用内置的通用 C6 固件。配置保存在这台设备内；云端授权仅在内存中缓存。':'Formlabs 专用测试固件，与多屏灵犀通用 C6 固件独立。设置保存在设备内，云端授权令牌仅缓存在运行内存中。',\n"
"'选择网络或填写 SSID，然后保存。':'选择或输入 Wi-Fi 名称后保存连接设置。',\n"
"'联网成功后，屏幕显示局域网 IP，配置热点自动关闭。请切回同一 Wi-Fi，再打开设备设置。':'连接成功后显示局域网 IP 并关闭配置热点。将手机或电脑连接至同一局域网，再访问设备设置。',\n"
"'开放网络可留空；密码不会回显，也不保存到浏览器。':'开放网络无需密码。密码不回显，不保存在浏览器中。'\n"
"};\n"
"function t(text){if(!uiEnglish)return uiChinese[text]||text;return uiStrings[text]||text;}\n"
"function printState(raw){\n"
"    if(!raw)return t('未知');\n"
"    const states={idle:['空闲','Idle'],printing:['打印中','Printing'],running:['打印中','Printing'],paused:['已暂停','Paused'],preprint:['准备中','Preparing'],postprint:['后处理中','Post-processing'],complete:['已完成','Complete'],completed:['已完成','Complete'],finished:['已完成','Complete'],offline:['离线','Offline'],error:['报错','Error'],cancelled:['已取消','Cancelled'],failed:['失败','Failed']};\n"
"    return states[raw.toLowerCase()]?.[uiEnglish?1:0]||raw;\n"
"}\n"
"const staticText=new WeakMap();\n"
"function applyLanguage(){\n"
"    if(document.documentElement)document.documentElement.lang=uiEnglish?'en':'zh-CN';\n"
"    if(!document.createTreeWalker)return;\n"
"    document.title='XH Multiscreen · Form Monitor C6';\n"
"    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);\n"
"    while(walker.nextNode()){\n"
"        const node=walker.currentNode,parent=node.parentElement;\n"
"        if(!parent||parent.closest('script,style,#printerList,#status,#identity,#health,#networks,#previewStatus,#previewCard'))continue;\n"
"        if(!staticText.has(node))staticText.set(node,node.nodeValue);\n"
"        const original=staticText.get(node),trimmed=original.trim();\n"
"        node.nodeValue=original.replace(trimmed,t(trimmed));\n"
"    }\n"
"    const nav=document.querySelector('nav');if(nav)nav.setAttribute('aria-label',t('设置导航'));\n"
"}\n"
"function setupAppearance(){const select=document.getElementById('appearance');if(!select)return;select.onchange=()=>{if(select.value==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.setAttribute('data-theme',select.value);};}\n"
"\n"
"setupAppearance();applyLanguage();\n"
"const $=id=>document.getElementById(id),encoder=new TextEncoder();let busy=false,alive=true,pollTimer,statusSource='选择网络或填写 SSID，然后保存。';\n"
"function status(text){statusSource=text;$('status').textContent=t(text);}\n"
"function controls(){for(const id of ['scan','ssid','password','connect','refresh'])$(id).disabled=busy;}\n"
"async function request(path,options={}){const r=await fetch(path,{cache:'no-store',...options,signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error(uiEnglish?'Request failed ('+r.status+')':'请求失败（'+r.status+'）');return r;}\n"
"async function info(){try{const data=await request('/api/info').then(r=>r.json());if(!alive)return;uiEnglish=data.language===1;$('pageLanguage').value=uiEnglish?1:0;applyLanguage();status(statusSource);$('identity').textContent=(data.ip==='0.0.0.0'?t('等待联网'):data.ip)+' · '+data.fw;\n"
"if(/^192\\.168\\.\\d{1,3}\\.\\d{1,3}$/.test(data.ip)||/^10\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}$/.test(data.ip)||/^172\\.(1[6-9]|2\\d|3[01])\\.\\d{1,3}\\.\\d{1,3}$/.test(data.ip))for(const link of document.querySelectorAll('a[href^=\"/standalone\"]'))link.href='http://'+data.ip+link.getAttribute('href');\n"
"}catch{status('连接超时，请检查设备网络。');}}\n"
"$('pageLanguage').onchange=()=>{uiEnglish=$('pageLanguage').value==='1';applyLanguage();status(statusSource);};\n"
"$('refresh').onclick=info;\n"
"$('scan').onclick=async()=>{if(busy)return;busy=true;controls();status('正在扫描附近的 2.4 GHz 网络…');try{let data=await request('/api/wifi/scan?start=1').then(r=>r.json());for(let i=0;data.busy&&i<24&&alive;i++){await new Promise(resolve=>setTimeout(resolve,500));data=await request('/api/wifi/scan').then(r=>r.json());}if(!alive)return;if(data.busy||data.error)throw Error(t('扫描失败，请稍后重试或手动填写 SSID。'));$('networks').replaceChildren();for(const network of data.networks||[]){if(!network.ssid)continue;const button=document.createElement('button');button.type='button';const name=document.createElement('span');name.textContent=network.ssid;const signal=document.createElement('small');signal.textContent=network.rssi+' dBm';button.append(name,signal);button.onclick=()=>{if($('ssid').value!==network.ssid)$('password').value='';$('ssid').value=network.ssid;$('password').focus();};$('networks').append(button);}status(data.networks?.length?'请选择网络并填写密码。':'没有发现网络，可手动填写 SSID。');}catch(e){if(alive)status(e.message);}finally{busy=false;if(alive)controls();}};\n"
"$('wifiForm').onsubmit=async event=>{event.preventDefault();if(busy)return;const ssid=$('ssid').value,password=$('password').value,n=encoder.encode(password).length;\n"
"if(!ssid||encoder.encode(ssid).length>32||ssid.includes('\\0'))return status('SSID 必须为 1–32 个 UTF-8 字节。');\n"
"if(password.includes('\\0')||!(n===0||(n>=8&&n<=63)||(n===64&&/^[0-9a-f]{64}$/i.test(password))))return status('密码应为 8–63 个字节，开放网络可留空。');\n"
"busy=true;controls();try{await request('/wifi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({ssid,password}).toString()});$('password').value='';status('网络已保存。热点会关闭，请切回同一 Wi-Fi，打开屏幕上的 IP 地址。');pollTimer=setTimeout(info,3000);}catch(e){if(alive)status(e.message);}finally{busy=false;if(alive)controls();}};\n"
"$('ssid').oninput=()=>{$('password').value='';};window.addEventListener('pagehide',()=>{alive=false;$('password').value='';clearTimeout(pollTimer);});info();\n"
"</script></body></html>\n"
"\n";
